      const setDeg = () => { let d = Math.atan2(comp.y - p.mouseY, p.mouseX - comp.x) * 180 / Math.PI; d = ((Math.round(d / 15) * 15) % 360 + 360) % 360; plan[cur].deg = d; plan[cur].touched = true; sync(); };
