        if (locked && !good) { p.noStroke(); p.fill(C.ok); p.textStyle(p.BOLD); p.textAlign(p.CENTER, p.CENTER); fit(`era ${txtOf(r)}`, W / 2, b.y + b.h + 24, 14, W - 24); }
