        if (!locked) { p.stroke(C.N); p.strokeWeight(2); p.noFill(); p.beginShape(); [...my].sort((u, w) => u[0] - w[0]).forEach(([x, y]) => p.vertex(v.X(x), v.Y(y))); p.endShape(); }
