    p.noStroke(); p.fill(C.ink); p.textAlign(p.CENTER, p.CENTER); p.textStyle(p.BOLD); p.textSize(15); p.text(sign > 0 ? '+' : '−', x + t / 2, y + t / 2 + 1);
