    demo(G) { const q = G.spots?.[0]; return q ? { from: { x: q.x + q.w / 2, y: q.y + q.h / 2 }, to: { x: G.dock.x + 20, y: G.dock.y + G.dock.h / 2 }, text: 'Arrastra junto a la base', ty: G.H * 0.5 } : null; },
    peek: G => ({ spots: G.spots, dock: G.dock }),
