      K.forEach((k, i) => { if (i % (r.op === '+' ? 2 : 2) === 0 || k === s.k) TK.label(p, C, `${k}`.replace('-', '−'), kx(i), G.trackY + 22, k === s.k ? C.brand : C.mute, 10, 28); });
      RK.knob(p, C, kx(ki), G.trackY, C.brand); G.kx = kx; G.knob = { x: kx(ki), y: G.trackY };
