    demo(G) { const q = G.src?.[0]; return q ? { from: { x: q.x + 20, y: q.y + 20 }, to: { x: G.ox + 30, y: G.oy + 30 }, text: 'Arrastra al marco', ty: G.trayY - 16 } : null; },
    peek: G => ({ src: G.src, zone: G.zone }),
