    demo(G) { const q = G.spots?.find(q => !q.inBox); return q ? { from: { x: q.x + 30, y: q.y + 18 }, to: { x: G.box.x + 40, y: G.box.y + 32 }, text: 'Arrastra a la caja', ty: G.cy + 56 } : null; },
    peek: G => ({ spots: G.spots, box: G.box }),
