        const tex = c ? `\\dfrac{${f[0]}\\cdot ${c.length > 2 ? `(${c})` : c}}{${mul(f[1])}\\cdot ${c.length > 2 ? `(${c})` : c}}` : `\\dfrac{${f[0]}}{${mul(f[1])}}`;
        TK.label(p, C, `$${tex}$`, b.x + b.w / 2, b.y + b.h / 2, C.ink, 15, b.w - 8);
