    demo: G => { const t = G.tray?.[0], l = G.leafBoxes?.[0]; return t && l ? { from: { x: t.x + t.w / 2, y: t.y + 18 }, to: l, text: 'Arrastra un primo', ty: t.y - 20 } : null; },
    peek: G => ({ tray: G.tray, leaves: G.leafBoxes }),
