    function expr() { const f = term(); let tex = f.tex; while (peek() === '+' || peek() === '-') { const op = tokens[i++] === '+' ? ' + ' : ' - ', n = term(); tex += op + (n.lead ? n.tex.replace(/^(-(?:\\frac\{[^{}]*\}\{[^{}]*\}|[\d.,\\]+))/, '($1)') : n.tex); } return { tex, neg: f.neg && tex === f.tex }; }
