  const sentences = t => String(t).replace(/([.!?…][»”")]?)\s+(?=[¿¡«"(—]?[A-ZÁÉÍÓÚÑ0-9])/g, '$1\u0001').split('\u0001').map(x => x.trim()).filter(Boolean);
