          + K.f(f, K.p([A, C, B], 'fa') + K.t((A[0] + C[0]) / 2, A[1] + 15, Math.abs(Math.round(v.x - p.A[0])), 's ta') + K.t(C[0] + (v.x > 10 ? -10 : 12), (C[1] + B[1]) / 2 + 5, Math.abs(Math.round(v.y - p.A[1])), 's ta')) + K.l(...A, A[0] + (B[0] - A[0]) * f, A[1] + (B[1] - A[1]) * f, 'lf gr');
