        + K.l(...B, ...K.at(...B, v.c * u4, 180 - g * f), 'lf gr') + K.t(B[0] + 30, 60, `cable: ${N(v.c)}`, 'tf', 'end') + K.f(f, K.t(F[0] + 8, F[1] - h * u4 / 2 + 22, h, 'tm', 'start')) + K.c(...top, 5, f < 1 ? 'fM' : Math.abs(v.c - Math.hypot(h, p.b2)) < 0.1 ? 'fo' : 'ff');
