    ini: () => ({ a: 2, b: 36 }), manijas: p => [{ k: 'a', min: 1, max: p.n - 1, paso: 1, rot: v => R(v.a), en: v => [24 + v.a * 292 / p.n, 26], de: x => (x - 24) * p.n / 292 }, { k: 'b', min: 1, max: p.n - 1, paso: 1, rot: v => R(v.b), en: v => [24 + v.b * 292 / p.n, 138], de: x => (x - 24) * p.n / 292 }],
