  const rec = (K, p) => p.f.map(([a, b, s], i) => { const y = 18 + i * 32; let h = ''; for (let k = 0; k < a; k++) h += K.r(18 + k * 26, y - 11, 22, 22, 'fa', 5); for (let k = 0; k < b; k++) h += K.c(134 + k * 26, y, 11, 'fg'); return h + K.t(278, y + 5, `= ${s}`, 'b', 'start'); }).join('');
